INSERT INTO `about_content` (`id`, `content`, `created_at`, `updated_at`) VALUES
(1, '{\"heroEyebrow\":\"Ni3 Cinema & SAN Test\",\"heroLine1\":\"We capture\",\"heroLine2\":\"what you feel.\",\"heroLine3\":\"Not just what you see.\",\"introText\":\"At SAN Photography, our team brings together creativity, experience, and passion to capture every special moment beautifully. From candid emotions to the smallest details, we work together to create photographs and films that tell your story.\",\"founderEyebrow\":\"Founder\",\"founderHeadingNormal\":\"The person behind\",\"founderHeadingItalic\":\"SAN.\",\"founderName\":\"SANDEEP BRAHMANKAR.\",\"founderRole\":\"Founder & Professional Photographer\",\"founderDescription\":\"SANDEEP is the founder and creative force behind SAN Photography, with 15+ years of professional experience in photography and cinematography. With a passion for storytelling and an eye for detail, he specializes in capturing weddings, pre-wedding celebrations, maternity moments, birthdays, kids, and other special occasions. His goal is to capture genuine emotions and create timeless photographs and cinematic films that clients can treasure for generations.\",\"founderQuote\":\"Every picture has a story, and our job is to capture it beautifully.\",\"founderImage\":\"\\/src\\/assets\\/team\\/SANDEEP%20BRAHMANKAR%20(FOUNDER)(VIDEOGRAPHER).jpeg\",\"teamEyebrow\":\"The Creative Team test\",\"teamHeadingNormal\":\"People behind\",\"teamHeadingItalic\":\"the frames.\",\"teamMembers\":[{\"id\":\"team-01\",\"number\":\"01\",\"name\":\"AIFAZ KHAN\",\"role\":\"Videographer\",\"description\":\"AIFAZ is a talented member of the SAN Photography team, contributing creativity and expertise to every project. He specializes in cinematography and works closely with clients to ensure every important moment is captured beautifully.\",\"image\":\"\\/src\\/assets\\/team\\/AHEFAZ%20KHAN%20(VIDEOGRAPHER).jpeg\"},{\"id\":\"team-02\",\"number\":\"02\",\"name\":\"BHAGWAT SHAHARE\",\"role\":\"Videographer\",\"description\":\"Bhagwat is part of the creative team at SAN Photography and plays an important role in delivering high-quality photographs and films. With a passion for photography and storytelling, he brings a unique creative perspective to every celebration.\",\"image\":\"\\/src\\/assets\\/team\\/BHAGWAT%20SHAHARE%20(VIDEOGRAPHER).jpeg\"},{\"id\":\"team-03\",\"number\":\"03\",\"name\":\"NITIN BRAHMANKAR\",\"role\":\"Photographer\",\"description\":\"A passionate and talented candid photographer with a keen eye for capturing genuine emotions, natural expressions, and unforgettable moments. Known for creative compositions and attention to detail, he specializes in weddings, pre-weddings, birthdays, maternity, kids, and special celebrations. His goal is to turn every beautiful moment into a timeless memory.\",\"image\":\"\"},{\"id\":\"team-04\",\"number\":\"04\",\"name\":\"YASH MESHRAM\",\"role\":\"Videographer\",\"description\":\"A skilled traditional photographer and videographer specializing in capturing every important moment with clarity and creativity. With a strong focus on weddings, ceremonies, birthdays, and celebrations, he ensures that every tradition, emotion, and memorable moment is beautifully documented for you to cherish forever.\",\"image\":\"\\/src\\/assets\\/team\\/YASH%20MESHRAM%20(VIDEOGRAPHER).jpeg\"},{\"id\":\"team-05\",\"number\":\"05\",\"name\":\"SAMYAK MESHRAM\",\"role\":\"Videographer\",\"description\":\"Samyak is a talented member of the SAN Photography team, contributing creativity and expertise to every project. He specializes in cinematography and works closely with clients to ensure every important moment is captured beautifully.\",\"image\":\"\\/src\\/assets\\/team\\/SAMAYK%20MESHRAM%20(VIDEOGRAPHER).jpeg\"},{\"id\":\"team-06\",\"number\":\"06\",\"name\":\"SARANG KANHERKAR\",\"role\":\"Photographer\",\"description\":\"Sarang is a talented traditional photographer who specializes in capturing weddings, ceremonies, celebrations, and meaningful moments. With a keen eye for detail, he beautifully documents every important tradition and emotion, creating timeless memories for every client.\",\"image\":\"\\/src\\/assets\\/team\\/SARANG%20KANERKAR%20(PHOTOGRAPHAR).jpeg\"},{\"id\":\"team-07\",\"number\":\"07\",\"name\":\"GURUSH MOHARKAR\",\"role\":\"Photographer\",\"description\":\"A skilled traditional photographer and videographer specializing in capturing every important moment with clarity and creativity. With a strong focus on weddings, ceremonies, birthdays, and celebrations, he ensures that every tradition, emotion, and memorable moment is beautifully documented for you to cherish forever.\",\"image\":\"\"}],\"ctaEyebrow\":\"SAN Photography\",\"ctaLine1\":\"Your story.\",\"ctaLine2\":\"Our frame.\",\"ctaDescription\":\"Every celebration has a story. We are here to preserve yours beautifully.\",\"ctaButtonText\":\"Start Your Story\",\"ctaButtonHref\":\"\\/contact\"}', '2026-09-10 03:02:30', '2026-09-10 03:38:30');
