INSERT INTO `home_content` (`id`, `content`, `updated_at`) VALUES
(1, '{\"slides\":[{\"id\":\"hero-1\",\"title\":\"Slide 01\",\"image\":\"/src/assets/hero/img1.jpg\"},{\"id\":\"hero-2\",\"title\":\"Slide 02\",\"image\":\"https://res.cloudinary.com/u8enqpdf/image/upload/v1789454040/san-photography/home/035A9037_wy0y0c.jpg\"},{\"id\":\"hero-3\",\"title\":\"Slide 03\",\"image\":\"https://res.cloudinary.com/u8enqpdf/image/upload/v1789454085/san-photography/home/DSC09544_zjvxmw.jpg\"},{\"id\":\"slide-1789453978505\",\"title\":\"Slide 04\",\"image\":\"https://res.cloudinary.com/u8enqpdf/image/upload/v1789454013/san-photography/home/035A7955_epi83b.jpg\"},{\"id\":\"slide-1789454013250\",\"title\":\"Slide 05\",\"image\":\"https://res.cloudinary.com/u8enqpdf/image/upload/v1789454027/san-photography/home/035A3185_xoh35h.jpg\"}],\"about\":{\"eyebrow\":\"Ni3 Cinema & SAN\",\"heading\":\"Capturing Your Precious Moments\",\"italicHeading\":\"With Love & Creativity\",\"intro\":\"Welcome to Ni3 Cinema & SAN — where beautiful moments become timeless memories.\",\"paragraph1\":\"We specialise in capturing the most special occasions of your life with creativity, care, and attention to every little detail. Whether it’s the happiness of a wedding, the excitement of a pre-wedding shoot, the celebration of a birthday, the beautiful journey of maternity, or the innocent smiles of children, we make sure every precious moment is captured naturally and beautifully.\",\"paragraph2\":\"Our goal is not just to take photographs, but to capture emotions, relationships, happiness, and memories that you can cherish for a lifetime.\",\"paragraph3\":\"From the first smile to the biggest celebration, we turn your special moments into beautiful stories.\",\"ending\":\"Your Moments. Our Passion. Memories Forever.\",\"buttonText\":\"Explore Our Work\",\"heroEyebrow\":\"Ni3 Cinema & SAN Test\",\"heroLine1\":\"We capture\",\"heroLine2\":\"what you feel.\",\"heroLine3\":\"Not just what you see.\",\"introText\":\"At SAN Photography, our team brings together creativity, experience, and passion to capture every special moment beautifully. From candid emotions to the smallest details, we work together to create photographs and films that tell your story.\",\"founderEyebrow\":\"Founder\",\"founderHeadingNormal\":\"The person behind\",\"founderHeadingItalic\":\"SAN.\",\"founderName\":\"SANDEEP BRAHMANKAR.\",\"founderRole\":\"Founder & Professional Photographer\",\"founderDescription\":\"SANDEEP is the founder and creative force behind SAN Photography, with 15+ years of professional experience in photography and cinematography. With a passion for storytelling and an eye for detail, he specializes in capturing weddings, pre-wedding celebrations, maternity moments, birthdays, kids, and other special occasions. His goal is to capture genuine emotions and create timeless photographs and cinematic films that clients can treasure for generations.\",\"founderQuote\":\"Every picture has a story, and our job is to capture it beautifully.\",\"founderImage\":\"/src/assets/team/SANDEEP%20BRAHMANKAR%20(FOUNDER)(VIDEOGRAPHER).jpeg\",\"teamEyebrow\":\"The Creative Team test\",\"teamHeadingNormal\":\"People behind\",\"teamHeadingItalic\":\"the frames.\",\"teamMembers\":[{\"id\":\"team-01\",\"number\":\"01\",\"name\":\"AIFAZ KHAN\",\"role\":\"Videographer\",\"description\":\"AIFAZ is a talented member of the SAN Photography team, contributing creativity and expertise to every project. He specializes in cinematography and works closely with clients to ensure every important moment is captured beautifully.\",\"image\":\"/src/assets/team/AHEFAZ%20KHAN%20(VIDEOGRAPHER).jpeg\"},{\"id\":\"team-02\",\"number\":\"02\",\"name\":\"BHAGWAT SHAHARE\",\"role\":\"Videographer\",\"description\":\"Bhagwat is part of the creative team at SAN Photography and plays an important role in delivering high-quality photographs and films. With a passion for photography and storytelling, he brings a unique creative perspective to every celebration.\",\"image\":\"/src/assets/team/BHAGWAT%20SHAHARE%20(VIDEOGRAPHER).jpeg\"},{\"id\":\"team-03\",\"number\":\"03\",\"name\":\"NITIN BRAHMANKAR\",\"role\":\"Photographer\",\"description\":\"A passionate and talented candid photographer with a keen eye for capturing genuine emotions, natural expressions, and unforgettable moments. Known for creative compositions and attention to detail, he specializes in weddings, pre-weddings, birthdays, maternity, kids, and special celebrations. His goal is to turn every beautiful moment into a timeless memory.\",\"image\":\"\"},{\"id\":\"team-04\",\"number\":\"04\",\"name\":\"YASH MESHRAM\",\"role\":\"Videographer\",\"description\":\"A skilled traditional photographer and videographer specializing in capturing every important moment with clarity and creativity. With a strong focus on weddings, ceremonies, birthdays, and celebrations, he ensures that every tradition, emotion, and memorable moment is beautifully documented for you to cherish forever.\",\"image\":\"/src/assets/team/YASH%20MESHRAM%20(VIDEOGRAPHER).jpeg\"},{\"id\":\"team-05\",\"number\":\"05\",\"name\":\"SAMYAK MESHRAM\",\"role\":\"Videographer\",\"description\":\"Samyak is a talented member of the SAN Photography team, contributing creativity and expertise to every project. He specializes in cinematography and works closely with clients to ensure every important moment is captured beautifully.\",\"image\":\"/src/assets/team/SAMAYK%20MESHRAM%20(VIDEOGRAPHER).jpeg\"},{\"id\":\"team-06\",\"number\":\"06\",\"name\":\"SARANG KANHERKAR\",\"role\":\"Photographer\",\"description\":\"Sarang is a talented traditional photographer who specializes in capturing weddings, ceremonies, celebrations, and meaningful moments. With a keen eye for detail, he beautifully documents every important tradition and emotion, creating timeless memories for every client.\",\"image\":\"/src/assets/team/SARANG%20KANERKAR%20(PHOTOGRAPHAR).jpeg\"},{\"id\":\"team-07\",\"number\":\"07\",\"name\":\"GURUSH MOHARKAR\",\"role\":\"Photographer\",\"description\":\"A skilled traditional photographer and videographer specializing in capturing every important moment with clarity and creativity. With a strong focus on weddings, ceremonies, birthdays, and celebrations, he ensures that every tradition, emotion, and memorable moment is beautifully documented for you to cherish forever.\",\"image\":\"\"}],\"ctaEyebrow\":\"SAN Photography\",\"ctaLine1\":\"Your story.\",\"ctaLine2\":\"Our frame.\",\"ctaDescription\":\"Every celebration has a story. We are here to preserve yours beautifully.\",\"ctaButtonText\":\"Start Your Story\",\"ctaButtonHref\":\"/contact\"},\"collage\":{\"heading\":\"What if it could never be recorded? A chronology of a couples journey where they vow together to be One.\",\"eyebrow\":\"WE ARE CREATING FICTION OUT OF REALITY\",\"images\":[\"https://res.cloudinary.com/u8enqpdf/image/upload/v1789454147/san-photography/home/DSC09826_mi3hj6.jpg\",\"/src/assets/portfolio/wedding/Kapil&Payal1/035A2163.jpg\",\"/src/assets/portfolio/wedding/Kapil&Payal1/035A2625.jpg\",\"/src/assets/portfolio/wedding/Kapil&Payal1/035A2709.jpg\",\"/src/assets/portfolio/wedding/Kapil&Payal1/035A2853.jpg\",\"/src/assets/portfolio/wedding/Kapil&Payal1/035A2869.jpg\",\"/src/assets/portfolio/wedding/Kapil&Payal1/035A2933.jpg\",\"/src/assets/portfolio/wedding/Kapil&Payal1/035A2984.jpg\",\"/src/assets/portfolio/wedding/Kapil&Payal1/035A2997.jpg\",\"/src/assets/portfolio/wedding/Kapil&Payal1/035A3022.jpg\",\"/src/assets/portfolio/wedding/Kapil&Payal1/035A3038.jpg\",\"/src/assets/portfolio/wedding/Kapil&Payal1/035A3082.jpg\",\"/src/assets/portfolio/wedding/Kapil&Payal1/035A3105.jpg\",\"/src/assets/portfolio/wedding/Kapil&Payal1/035A3176.jpg\",\"/src/assets/portfolio/wedding/Kapil&Payal1/035A3185.jpg\",\"/src/assets/portfolio/wedding/Kapil&Payal1/035A3213.jpg\",\"/src/assets/portfolio/wedding/Kapil&Payal1/035A3269.jpg\",\"/src/assets/portfolio/wedding/Kapil&Payal1/035A3514.jpg\",\"/src/assets/portfolio/wedding/Kapil&Payal1/035A3553.jpg\",\"/src/assets/portfolio/wedding/Kapil&Payal1/035A3558.jpg\",\"/src/assets/portfolio/wedding/Kapil&Payal1/035A3589.jpg\",\"/src/assets/portfolio/wedding/Kapil&Payal1/035A7514.jpg\",\"/src/assets/portfolio/wedding/Kapil&Payal1/035A7525.jpg\",\"/src/assets/portfolio/wedding/Kapil&Payal1/035A7545.jpg\",\"/src/assets/portfolio/wedding/Kapil&Payal1/035A7637.jpg\",\"/src/assets/portfolio/wedding/Kapil&Payal1/035A7651.jpg\",\"/src/assets/portfolio/wedding/Kapil&Payal1/035A7672.jpg\",\"/src/assets/portfolio/wedding/Kapil&Payal1/035A7698.jpg\",\"/src/assets/portfolio/wedding/Kapil&Payal1/035A7720.jpg\",\"/src/assets/portfolio/wedding/Kapil&Payal1/035A7746.jpg\",\"/src/assets/portfolio/wedding/Kapil&Payal1/035A7762.jpg\",\"/src/assets/portfolio/wedding/Kapil&Payal1/035A7955.jpg\"]},\"couples\":{\"heading\":\"Real love\",\"italicHeading\":\"stories.\",\"items\":[{\"id\":\"couple-0\",\"name\":\"Kapil & Payal\",\"img\":\"https://res.cloudinary.com/u8enqpdf/image/upload/v1789461699/san-photography/home/DSC00039_elbugq.jpg\"},{\"id\":\"couple-1\",\"name\":\"Pratik & Megha\",\"img\":\"/src/assets/portfolio/wedding/PRATIK%20&%20MEGHA/DSC00039.jpg\"},{\"id\":\"couple-2\",\"name\":\"Tanmay & Achal\",\"img\":\"/src/assets/portfolio/wedding/Tanmay&Achal/01.jpg\"},{\"id\":\"couple-3\",\"name\":\"Kapil & Payal\",\"img\":\"/src/assets/portfolio/wedding/Kapil&Payal1/02.jpg\"},{\"id\":\"couple-4\",\"name\":\"Pratik & Megha\",\"img\":\"/src/assets/portfolio/wedding/PRATIK%20&%20MEGHA/DSC00039.jpg\"},{\"id\":\"couple-5\",\"name\":\"Tanmay & Achal\",\"img\":\"/src/assets/portfolio/wedding/Tanmay&Achal/01.jpg\"},{\"id\":\"couple-6\",\"name\":\"Kapil & Payal\",\"img\":\"/src/assets/portfolio/wedding/Kapil&Payal1/02.jpg\"},{\"id\":\"couple-7\",\"name\":\"Pratik & Megha\",\"img\":\"/src/assets/portfolio/wedding/PRATIK%20&%20MEGHA/DSC00039.jpg\"}]},\"videos\":{\"eyebrow\":\"WATCH OUR FILMS\",\"heading\":\"Moving memories that tell\",\"italicHeading\":\"your story.\",\"items\":[{\"id\":\"video-1\",\"title\":\"Film 1\",\"url\":\"/src/assets/portfolio/wedding/video2/VIDEOS/27%20REEL.MP4\"},{\"id\":\"video-2\",\"title\":\"Film 2\",\"url\":\"/src/assets/portfolio/wedding/video2/VIDEOS/KAPIL%20PAYAL%20WEDDING%20FILM%20HIGH%20CORRECTION.mp4\"}]},\"soulCinema\":{\"eyebrow\":\"AWARD WINNING FILMS\",\"brandEyebrow\":\"NI3 CINEMA & SAN\",\"heading\":\"SOUL + CINEMA\",\"description\":\"Every frame tells a story — captured with heart, framed with soul, and made to be relived for a lifetime.\",\"videoUrl\":\"/src/assets/portfolio/wedding/video2/VIDEOS/KAPIL%20PAYAL%20WEDDING%20FILM%20HIGH%20CORRECTION.mp4\"},\"testimonials\":{\"eyebrow\":\"KIND WORDS\",\"items\":[{\"id\":\"test-1\",\"quote\":\"Every photograph brought our memories back to life. The moments feel natural, emotional and truly ours.\",\"author\":\"A HAPPY SAN FAMILY\"},{\"id\":\"test-2\",\"quote\":\"They captured the laughter, the tears and all the little details we never wanted to forget.\",\"author\":\"A HAPPY COUPLE\"},{\"id\":\"test-3\",\"quote\":\"Beautiful work, wonderful team and memories we will cherish for a lifetime.\",\"author\":\"A HAPPY CLIENT\"}]}}', '2026-09-15 08:41:43');
