(1, '{\"slides\":[{\"id\":\"slide-1789454013250\",\"title\":\"slide 1\",\"image\":\"https://res.cloudinary.com/u8enqpdf/image/upload/v1789454027/san-photography/home/035A3185_xoh35h.jpg\"},{\"id\":\"slide-1789472858632\",\"title\":\"slide 2\",\"image\":\"https://res.cloudinary.com/u8enqpdf/image/upload/v1789472900/san-photography/home/035A3589_s0ebee.jpg\"},{\"id\":\"slide-1789739936802\",\"title\":\"Slide 03\",\"image\":\"/uploads/images/home/7c68617e903d6166a23f1b67-035A8780.jpg\"}],\"about\":{\"eyebrow\":\"Ni3 Cinema & SAN test 02\",\"heading\":\"Capturing Your Precious Moments\",\"italicHeading\":\"With Love & Creativity\",\"intro\":\"Welcome to Ni3 Cinema & SAN - where beautiful moments become timeless memories.\",\"paragraph1\":\"We specialise in capturing the most special occasions of your life with creativity, care, and attention to every little detail. Whether it\'s the happiness of a wedding, the excitement of a pre-wedding shoot, the celebration of a birthday, the beautiful journey of maternity, or the innocent smiles of children, we make sure every precious moment is captured naturally and beautifully.\",\"paragraph2\":\"Our goal is not just to take photographs, but to capture emotions, relationships, happiness, and memories that you can cherish for a lifetime.\",\"paragraph3\":\"From the first smile to the biggest celebration, we turn your special moments into beautiful stories.\",\"ending\":\"Your Moments. Our Passion. Memories Forever.\",\"buttonText\":\"\",\"heroEyebrow\":\"Ni3 Cinema & SAN Test\",\"heroLine1\":\"We capture\",\"heroLine2\":\"what you feel.\",\"heroLine3\":\"Not just what you see.\",\"introText\":\"At SAN Photography, our team brings together creativity, experience, and passion to capture every special moment beautifully. From candid emotions to the smallest details, we work together to create photographs and films that tell your story.\",\"founderEyebrow\":\"Founder\",\"founderHeadingNormal\":\"The person behind\",\"founderHeadingItalic\":\"SAN.\",\"founderName\":\"SANDEEP BRAHMANKAR.\",\"founderRole\":\"Founder & Professional Photographer\",\"founderDescription\":\"SANDEEP is the founder and creative force behind SAN Photography, with 15+ years of professional experience in photography and cinematography. With a passion for storytelling and an eye for detail, he specializes in capturing weddings, pre-wedding celebrations, maternity moments, birthdays, kids, and other special occasions. His goal is to capture genuine emotions and create timeless photographs and cinematic films that clients can treasure for generations.\",\"founderQuote\":\"Every picture has a story, and our job is to capture it beautifully.\",\"founderImage\":\"/src/assets/team/SANDEEP%20BRAHMANKAR%20(FOUNDER)(VIDEOGRAPHER).jpeg\",\"teamEyebrow\":\"The Creative Team test\",\"teamHeadingNormal\":\"People behind\",\"teamHeadingItalic\":\"the frames.\",\"teamMembers\":[{\"id\":\"team-01\",\"number\":\"01\",\"name\":\"AIFAZ KHAN\",\"role\":\"Videographer\",\"description\":\"AIFAZ is a talented member of the SAN Photography team, contributing creativity and expertise to every project. He specializes in cinematography and works closely with clients to ensure every important moment is captured beautifully.\",\"image\":\"/src/assets/team/AHEFAZ%20KHAN%20(VIDEOGRAPHER).jpeg\"},{\"id\":\"team-02\",\"number\":\"02\",\"name\":\"BHAGWAT SHAHARE\",\"role\":\"Videographer\",\"description\":\"Bhagwat is part of the creative team at SAN Photography and plays an important role in delivering high-quality photographs and films. With a passion for photography and storytelling, he brings a unique creative perspective to every celebration.\",\"image\":\"/src/assets/team/BHAGWAT%20SHAHARE%20(VIDEOGRAPHER).jpeg\"},{\"id\":\"team-03\",\"number\":\"03\",\"name\":\"NITIN BRAHMANKAR\",\"role\":\"Photographer\",\"description\":\"A passionate and talented candid photographer with a keen eye for capturing genuine emotions, natural expressions, and unforgettable moments. Known for creative compositions and attention to detail, he specializes in weddings, pre-weddings, birthdays, maternity, kids, and special celebrations. His goal is to turn every beautiful moment into a timeless memory.\",\"image\":\"\"},{\"id\":\"team-04\",\"number\":\"04\",\"name\":\"YASH MESHRAM\",\"role\":\"Videographer\",\"description\":\"A skilled traditional photographer and videographer specializing in capturing every important moment with clarity and creativity. With a strong focus on weddings, ceremonies, birthdays, and celebrations, he ensures that every tradition, emotion, and memorable moment is beautifully documented for you to cherish forever.\",\"image\":\"/src/assets/team/YASH%20MESHRAM%20(VIDEOGRAPHER).jpeg\"},{\"id\":\"team-05\",\"number\":\"05\",\"name\":\"SAMYAK MESHRAM\",\"role\":\"Videographer\",\"description\":\"Samyak is a talented member of the SAN Photography team, contributing creativity and expertise to every project. He specializes in cinematography and works closely with clients to ensure every important moment is captured beautifully.\",\"image\":\"/src/assets/team/SAMAYK%20MESHRAM%20(VIDEOGRAPHER).jpeg\"},{\"id\":\"team-06\",\"number\":\"06\",\"name\":\"SARANG KANHERKAR\",\"role\":\"Photographer\",\"description\":\"Sarang is a talented traditional photographer who specializes in capturing weddings, ceremonies, celebrations, and meaningful moments. With a keen eye for detail, he beautifully documents every important tradition and emotion, creating timeless memories for every client.\",\"image\":\"/src/assets/team/SARANG%20KANERKAR%20(PHOTOGRAPHAR).jpeg\"},{\"id\":\"team-07\",\"number\":\"07\",\"name\":\"GURUSH MOHARKAR\",\"role\":\"Photographer\",\"description\":\"A skilled traditional photographer and videographer specializing in capturing every important moment with clarity and creativity. With a strong focus on weddings, ceremonies, birthdays, and celebrations, he ensures that every tradition, emotion, and memorable moment is beautifully documented for you to cherish forever.\",\"image\":\"\"}],\"ctaEyebrow\":\"SAN Photography\",\"ctaLine1\":\"Your story.\",\"ctaLine2\":\"Our frame.\",\"ctaDescription\":\"Every celebration has a story. We are here to preserve yours beautifully.\",\"ctaButtonText\":\"Start Your Story\",\"ctaButtonHref\":\"/contact\"},\"collage\":{\"heading\":\"What if it could never be recorded? A chronology of a couples journey where they vow together to be One.\",\"eyebrow\":\"WE ARE CREATING FICTION OUT OF REALITY\",\"images\":[{\"url\":\"/uploads/images/home/db70a47cc428b6706e9e10d2-035A8944.jpg\",\"visible\":true},{\"url\":\"/src/assets/portfolio/wedding/Kapil&Payal1/035A2163.jpg\",\"visible\":true},{\"url\":\"/src/assets/portfolio/wedding/Kapil&Payal1/035A2625.jpg\",\"visible\":true},{\"url\":\"/src/assets/portfolio/wedding/Kapil&Payal1/035A2709.jpg\",\"visible\":true},{\"url\":\"/src/assets/portfolio/wedding/Kapil&Payal1/035A2853.jpg\",\"visible\":true},{\"url\":\"/src/assets/portfolio/wedding/Kapil&Payal1/035A2869.jpg\",\"visible\":true},{\"url\":\"/src/assets/portfolio/wedding/Kapil&Payal1/035A2933.jpg\",\"visible\":true},{\"url\":\"/src/assets/portfolio/wedding/Kapil&Payal1/035A2984.jpg\",\"visible\":true},{\"url\":\"/src/assets/portfolio/wedding/Kapil&Payal1/035A2997.jpg\",\"visible\":true},{\"url\":\"/src/assets/portfolio/wedding/Kapil&Payal1/035A3022.jpg\",\"visible\":true},{\"url\":\"/src/assets/portfolio/wedding/Kapil&Payal1/035A3038.jpg\",\"visible\":true},{\"url\":\"/src/assets/portfolio/wedding/Kapil&Payal1/035A3082.jpg\",\"visible\":true},{\"url\":\"/src/assets/portfolio/wedding/Kapil&Payal1/035A3105.jpg\",\"visible\":true},{\"url\":\"/src/assets/portfolio/wedding/Kapil&Payal1/035A3176.jpg\",\"visible\":true},{\"url\":\"/src/assets/portfolio/wedding/Kapil&Payal1/035A3185.jpg\",\"visible\":true},{\"url\":\"/src/assets/portfolio/wedding/Kapil&Payal1/035A3213.jpg\",\"visible\":true},{\"url\":\"/src/assets/portfolio/wedding/Kapil&Payal1/035A3269.jpg\",\"visible\":true},{\"url\":\"/src/assets/portfolio/wedding/Kapil&Payal1/035A3514.jpg\",\"visible\":true},{\"url\":\"/src/assets/portfolio/wedding/Kapil&Payal1/035A3553.jpg\",\"visible\":true},{\"url\":\"/src/assets/portfolio/wedding/Kapil&Payal1/035A3558.jpg\",\"visible\":true},{\"url\":\"/src/assets/portfolio/wedding/Kapil&Payal1/035A3589.jpg\",\"visible\":true},{\"url\":\"/src/assets/portfolio/wedding/Kapil&Payal1/035A7514.jpg\",\"visible\":true},{\"url\":\"/src/assets/portfolio/wedding/Kapil&Payal1/035A7525.jpg\",\"visible\":true},{\"url\":\"/src/assets/portfolio/wedding/Kapil&Payal1/035A7545.jpg\",\"visible\":true},{\"url\":\"/src/assets/portfolio/wedding/Kapil&Payal1/035A7637.jpg\",\"visible\":true},{\"url\":\"/src/assets/portfolio/wedding/Kapil&Payal1/035A7651.jpg\",\"visible\":true},{\"url\":\"/src/assets/portfolio/wedding/Kapil&Payal1/035A7672.jpg\",\"visible\":true},{\"url\":\"/src/assets/portfolio/wedding/Kapil&Payal1/035A7698.jpg\",\"visible\":true},{\"url\":\"/src/assets/portfolio/wedding/Kapil&Payal1/035A7720.jpg\",\"visible\":true},{\"url\":\"/src/assets/portfolio/wedding/Kapil&Payal1/035A7746.jpg\",\"visible\":true},{\"url\":\"/src/assets/portfolio/wedding/Kapil&Payal1/035A7762.jpg\",\"visible\":true},{\"url\":\"/src/assets/portfolio/wedding/Kapil&Payal1/035A7955.jpg\",\"visible\":true}]},\"couples\":{\"heading\":\"Real love test\",\"italicHeading\":\"stories.\",\"items\":[{\"id\":\"couple-6\",\"name\":\"test & 1\",\"img\":\"/uploads/images/home/941b3da08fd25c88216ea220-035A7955.jpg\",\"slug\":\"kapil-payal\"},{\"id\":\"couple-7\",\"name\":\"test & 2\",\"img\":\"/uploads/images/home/fefc38ef6016b1f3aa326d3b-035A8448.jpg\",\"slug\":\"pratik-megha\"},{\"id\":\"couple-5\",\"name\":\"test & 3\",\"img\":\"/src/assets/portfolio/wedding/Tanmay&Achal/01.jpg\",\"slug\":\"tanmay-achal\"},{\"id\":\"couple-3\",\"name\":\"test & 4\",\"img\":\"https://res.cloudinary.com/u8enqpdf/image/upload/v1789487467/san-photography/home/035A3558_jwfxlf.jpg\",\"slug\":\"rohan-anjali\"},{\"id\":\"couple-1789484994495\",\"name\":\"test & 5\",\"img\":\"https://res.cloudinary.com/u8enqpdf/image/upload/v1789485008/san-photography/home/035A3553_yeabky.jpg\",\"slug\":\"story-05\"},{\"id\":\"couple-4\",\"name\":\"test & 6\",\"img\":\"https://res.cloudinary.com/u8enqpdf/image/upload/v1789527815/san-photography/home/DSC05871_qvizix.jpg\",\"slug\":\"story-05\"}]},\"videos\":{\"eyebrow\":\"WATCH OUR FILMS\",\"heading\":\"Moving memories that tell\",\"italicHeading\":\"your story.\",\"items\":[{\"id\":\"video-1\",\"title\":\"Film 1\",\"url\":\"/uploads/videos/home/c3cb3bc27bc11cfddd764fc3-KAPIL-PAYAL-WEDDING-FILM-HIGH-CORRECTION-compressed-1.mp4\"},{\"id\":\"video-2\",\"title\":\"Film 2\",\"url\":\"/src/assets/portfolio/wedding/video2/VIDEOS/KAPIL%20PAYAL%20WEDDING%20FILM%20HIGH%20CORRECTION.mp4\"},{\"id\":\"video-1789542892842\",\"title\":\"test video 3\",\"url\":\"https://res.cloudinary.com/u8enqpdf/video/upload/v1789543572/san-photography/home/video-chunk_bqkmot.mp4\"},{\"id\":\"video-1789543536641\",\"title\":\"test video 4\",\"url\":\"https://res.cloudinary.com/u8enqpdf/video/upload/v1789543578/san-photography/home/video-chunk_b8kuwe.mp4\"}]},\"soulCinema\":{\"eyebrow\":\"AWARD WINNING FILMS\",\"brandEyebrow\":\"NI3 CINEMA & SAN\",\"heading\":\"SOUL + CINEMA\",\"description\":\"Every frame tells a story - captured with heart, framed with soul, and made to be relived for a lifetime.\",\"videoUrl\":\"/src/assets/portfolio/wedding/video2/VIDEOS/KAPIL%20PAYAL%20WEDDING%20FILM%20HIGH%20CORRECTION.mp4\"},\"testimonials\":{\"eyebrow\":\"KIND WORDS\",\"items\":[{\"id\":\"test-1\",\"quote\":\"Every photograph brought our memories back to life. The moments feel natural, emotional and truly ours.\",\"author\":\"A HAPPY SAN FAMILY\"},{\"id\":\"test-2\",\"quote\":\"They captured the laughter, the tears and all the little details we never wanted to forget.\",\"author\":\"A HAPPY COUPLE\"},{\"id\":\"test-3\",\"quote\":\"Beautiful work, wonderful team and memories we will cherish for a lifetime.\",\"author\":\"A HAPPY CLIENT\"}]}}', '{\"heroEyebrow\":\"Ni3 Cinema & SAN Test\",\"heroLine1\":\"We capture\",\"heroLine2\":\"what you feel.\",\"heroLine3\":\"Not just what you see.\",\"introText\":\"At SAN Photography, our team brings together creativity, experience, and passion to capture every special moment beautifully. From candid emotions to the smallest details, we work together to create photographs and films that tell your story.\",\"founderEyebrow\":\"Founder\",\"founderHeadingNormal\":\"The person behind\",\"founderHeadingItalic\":\"SAN.\",\"founderName\":\"SANDEEP BRAHMANKAR.\",\"founderRole\":\"Founder & Professional Photographer\",\"founderDescription\":\"SANDEEP is the founder and creative force behind SAN Photography, with 15+ years of professional experience in photography and cinematography. With a passion for storytelling and an eye for detail, he specializes in capturing weddings, pre-wedding celebrations, maternity moments, birthdays, kids, and other special occasions. His goal is to capture genuine emotions and create timeless photographs and cinematic films that clients can treasure for generations.\",\"founderQuote\":\"Every picture has a story, and our job is to capture it beautifully.\",\"founderImage\":\"/src/assets/team/SANDEEP%20BRAHMANKAR%20(FOUNDER)(VIDEOGRAPHER).jpeg\",\"teamEyebrow\":\"The Creative Team test 1\",\"teamHeadingNormal\":\"People behind\",\"teamHeadingItalic\":\"the frames.\",\"teamMembers\":[{\"id\":\"team-01\",\"number\":\"011\",\"name\":\"AIFAZ KHAN\",\"role\":\"Videographer\",\"description\":\"AIFAZ is a talented member of the SAN Photography team, contributing creativity and expertise to every project. He specializes in cinematography and works closely with clients to ensure every important moment is captured beautifully.\",\"image\":\"https://res.cloudinary.com/u8enqpdf/image/upload/v1789473272/san-photography/about/035A3082_kae78c.jpg\"},{\"id\":\"team-02\",\"number\":\"02\",\"name\":\"BHAGWAT SHAHARE\",\"role\":\"Videographer\",\"description\":\"Bhagwat is part of the creative team at SAN Photography and plays an important role in delivering high-quality photographs and films. With a passion for photography and storytelling, he brings a unique creative perspective to every celebration.\",\"image\":\"/src/assets/team/BHAGWAT%20SHAHARE%20(VIDEOGRAPHER).jpeg\"},{\"id\":\"team-03\",\"number\":\"03\",\"name\":\"NITIN BRAHMANKAR\",\"role\":\"Photographer\",\"description\":\"A passionate and talented candid photographer with a keen eye for capturing genuine emotions, natural expressions, and unforgettable moments. Known for creative compositions and attention to detail, he specializes in weddings, pre-weddings, birthdays, maternity, kids, and special celebrations. His goal is to turn every beautiful moment into a timeless memory.\",\"image\":\"\"},{\"id\":\"team-04\",\"number\":\"04\",\"name\":\"YASH MESHRAM\",\"role\":\"Videographer\",\"description\":\"A skilled traditional photographer and videographer specializing in capturing every important moment with clarity and creativity. With a strong focus on weddings, ceremonies, birthdays, and celebrations, he ensures that every tradition, emotion, and memorable moment is beautifully documented for you to cherish forever.\",\"image\":\"/src/assets/team/YASH%20MESHRAM%20(VIDEOGRAPHER).jpeg\"},{\"id\":\"team-05\",\"number\":\"05\",\"name\":\"SAMYAK MESHRAM\",\"role\":\"Videographer\",\"description\":\"Samyak is a talented member of the SAN Photography team, contributing creativity and expertise to every project. He specializes in cinematography and works closely with clients to ensure every important moment is captured beautifully.\",\"image\":\"/src/assets/team/SAMAYK%20MESHRAM%20(VIDEOGRAPHER).jpeg\"},{\"id\":\"team-06\",\"number\":\"06\",\"name\":\"SARANG KANHERKAR\",\"role\":\"Photographer\",\"description\":\"Sarang is a talented traditional photographer who specializes in capturing weddings, ceremonies, celebrations, and meaningful moments. With a keen eye for detail, he beautifully documents every important tradition and emotion, creating timeless memories for every client.\",\"image\":\"/src/assets/team/SARANG%20KANERKAR%20(PHOTOGRAPHAR).jpeg\"},{\"id\":\"team-07\",\"number\":\"07\",\"name\":\"GURUSH MOHARKAR\",\"role\":\"Photographer\",\"description\":\"A skilled traditional photographer and videographer specializing in capturing every important moment with clarity and creativity. With a strong focus on weddings, ceremonies, birthdays, and celebrations, he ensures that every tradition, emotion, and memorable moment is beautifully documented for you to cherish forever.\",\"image\":\"\"}],\"ctaEyebrow\":\"SAN Photography\",\"ctaLine1\":\"Your story.\",\"ctaLine2\":\"Our frame.\",\"ctaDescription\":\"Every celebration has a story. We are here to preserve yours beautifully.\",\"ctaButtonText\":\"Start Your Story\",\"ctaButtonHref\":\"/contact\"}', NULL, '{\"heroEyebrow\":\"SAN / PORTFOLIO Test 02\",\"heroLabel\":\"Selected Works & Films\",\"heroLine1\":\"Timeless\",\"heroLine2\":\"moments,\",\"heroLine3\":\"beautifully captured.\",\"heroVideoUrl\":\"https://res.cloudinary.com/u8enqpdf/video/upload/v1789048370/san-photography/portfolio/video-chunk_fbv6yl.mp4\",\"stories\":[{\"id\":\"kapil-payal\",\"title\":\"KAPIL & PAYAL1\",\"date\":\"October 24, 2024\",\"strapline\":\"A homecoming, dressed in gold\",\"paragraphs\":[\"From the horse that carried Kapil through Nagpur to the quiet moments between rituals, every frame here is a visual heirloom of their beautiful beginning.\"],\"videoUrl\":\"https://res.cloudinary.com/u8enqpdf/video/upload/v1789052859/san-photography/portfolio/video-chunk_yemgbo.mp4\",\"images\":[{\"url\":\"https://res.cloudinary.com/u8enqpdf/image/upload/v1789194367/san-photography/portfolio/035A2625_vc1vf5.jpg\",\"visible\":true},{\"url\":\"https://res.cloudinary.com/u8enqpdf/image/upload/v1789052272/san-photography/portfolio/035A3269_uohjg2.